import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type WalkthroughChecklistProps = Record<string, any>;

const IconRenderer: React.FC<{ type: string; color: string; size: number }> = ({
  type,
  color,
  size,
}) => {
  const commonProps = {
    xmlns: "http://www.w3.org/2000/svg",
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: color,
    strokeWidth: "2",
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
  };

  switch (type) {
    case "document":
      return (
        <svg {...commonProps}>
          <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
          <polyline points="14 2 14 8 20 8" />
          <line x1="16" y1="13" x2="8" y2="13" />
          <line x1="16" y1="17" x2="8" y2="17" />
          <polyline points="10 9 9 9 8 9" />
        </svg>
      );
    case "clipboard":
      return (
        <svg {...commonProps}>
          <path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2" />
          <rect x="8" y="2" width="8" height="4" rx="1" ry="1" />
        </svg>
      );
    case "search":
      return (
        <svg {...commonProps}>
          <circle cx="11" cy="11" r="8" />
          <line x1="21" y1="21" x2="16.65" y2="16.65" />
        </svg>
      );
    case "calendar":
      return (
        <svg {...commonProps}>
          <rect x="3" y="4" width="18" height="18" rx="2" ry="2" />
          <line x1="16" y1="2" x2="16" y2="6" />
          <line x1="8" y1="2" x2="8" y2="6" />
          <line x1="3" y1="10" x2="21" y2="10" />
        </svg>
      );
    default:
      return null;
  }
};

const WalkthroughChecklist: React.FC<WalkthroughChecklistProps> = ({
  backgroundColor = "#E5E7E1",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Your 11-Month Walkthrough Checklist",
  cardColor = "#FDFBF7",
  accentColor = "#7D9783",
  textColor = "#2D3330",
  steps = [
    { text: "Start a Google Doc", icon: "document" },
    { text: "Know Your Subcontractors", icon: "clipboard" },
    { text: "Hire a Third-Party Inspector", icon: "search" },
    { text: "File the Request on Time", icon: "calendar" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Card Intro Animation
  const cardScale = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 90 },
  });
  const cardOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: width * 0.65,
          backgroundColor: cardColor,
          borderRadius: 24,
          padding: "70px 80px",
          boxShadow: "0 20px 40px rgba(0,0,0,0.06)",
          display: "flex",
          flexDirection: "column",
          transform: `scale(${cardScale})`,
          opacity: cardOpacity,
          transition: "none",
        }}
      >
        <h1
          style={{
            fontSize: 48,
            fontWeight: 700,
            color: textColor,
            margin: 0,
            marginBottom: 60,
            textAlign: "center",
            letterSpacing: "-0.02em",
          }}
        >
          {title}
        </h1>

        <div style={{ display: "flex", flexDirection: "column", gap: 32 }}>
          {steps.map((step, index) => {
            // Stagger each step
            const stepStartFrame = 20 + index * 30;
            const checkmarkStartFrame = stepStartFrame + 20;

            const slideOffset = spring({
              frame: frame - stepStartFrame,
              fps,
              config: { damping: 14, stiffness: 80 },
            });

            const stepOpacity = interpolate(
              frame - stepStartFrame,
              [0, 15],
              [0, 1],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            const translateX = interpolate(
              slideOffset,
              [0, 1],
              [width * 0.1, 0]
            );

            // Checkmark animation
            const checkProgress = spring({
              frame: frame - checkmarkStartFrame,
              fps,
              config: { damping: 12, stiffness: 100 },
            });

            // The length of the polyline used for the checkmark is approx 22
            const checkPathLength = 30;
            const dashOffset = interpolate(
              checkProgress,
              [0, 1],
              [checkPathLength, 0],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            // Background of the checkbox animating slightly
            const checkboxBgOpacity = interpolate(
              checkProgress,
              [0, 1],
              [0, 1],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  flexDirection: "row",
                  opacity: stepOpacity,
                  transform: `translateX(${translateX}px)`,
                  transition: "none",
                }}
              >
                {/* Icon Box */}
                <div
                  style={{
                    width: 72,
                    height: 72,
                    borderRadius: 16,
                    backgroundColor: `${accentColor}1A`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    marginRight: 24,
                    flexShrink: 0,
                  }}
                >
                  <IconRenderer type={step.icon} color={accentColor} size={32} />
                </div>

                {/* Step Text */}
                <span
                  style={{
                    fontSize: 34,
                    fontWeight: 500,
                    color: textColor,
                  }}
                >
                  {step.text}
                </span>

                {/* Checkbox */}
                <div
                  style={{
                    marginLeft: "auto",
                    width: 44,
                    height: 44,
                    borderRadius: 10,
                    border: `2.5px solid ${accentColor}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    position: "relative",
                    overflow: "hidden",
                    backgroundColor: `rgba(125, 151, 131, ${checkboxBgOpacity * 0.1})`,
                    transition: "none",
                  }}
                >
                  <svg
                    width="28"
                    height="28"
                    viewBox="0 0 24 24"
                    fill="none"
                    xmlns="http://www.w3.org/2000/svg"
                    style={{
                      transition: "none",
                    }}
                  >
                    <polyline
                      points="20 6 9 17 4 12"
                      stroke={accentColor}
                      strokeWidth="3.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeDasharray={checkPathLength}
                      strokeDashoffset={dashOffset}
                      style={{ transition: "none" }}
                    />
                  </svg>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default WalkthroughChecklist;